//! Conformance against the Python reference implementation.
//!
//! `fixtures/golden/predictions.jsonl` is generated by `tools/gen_golden.py` from the
//! pinned `ttucs` package. Every row is a description plus the CatID, FX name,
//! keywords and filename that `ttucs` produced for it.
//!
//! `fx_name` and `keywords` are computed from `parsed_description`, the description
//! the reference pipeline extracted from the transcript, not from the raw input. The
//! slate parser that produces it is not part of this crate yet, so the corpus records
//! it alongside the input rather than making this test depend on a port that does not
//! exist.
//!
//! A failure here means the Rust port has diverged from the reference. It is never
//! fixed by loosening the assertion: either the port is wrong, or the pinned version
//! moved and the corpus needs regenerating with a changelog entry.

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::path::PathBuf;

use serde::Deserialize;
use slate_ucs::{make_fx_name, make_keywords, UcsFilename};

#[derive(Debug, Deserialize)]
struct GoldenRow {
    description: String,
    parsed_description: String,
    cat_id: String,
    fx_name: String,
    keywords: Vec<String>,
    filename: String,
}

fn corpus_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/golden/predictions.jsonl")
}

fn load_corpus() -> Vec<GoldenRow> {
    let path = corpus_path();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str::<GoldenRow>(line).expect("golden row is valid JSON"))
        .collect()
}

#[test]
fn corpus_is_present_and_non_trivial() {
    let rows = load_corpus();

    assert!(
        rows.len() >= 400,
        "expected at least 400 golden rows, found {}",
        rows.len()
    );
}

#[test]
fn fx_name_matches_the_reference() {
    let mut mismatches = Vec::new();
    for row in load_corpus() {
        let actual = make_fx_name(&row.parsed_description, 25);
        if actual != row.fx_name {
            mismatches.push(format!(
                "{:?}: expected {:?}, got {:?}",
                row.parsed_description, row.fx_name, actual
            ));
        }
    }

    assert!(
        mismatches.is_empty(),
        "{} fx_name mismatches:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}

#[test]
fn keywords_match_the_reference() {
    let mut mismatches = Vec::new();
    for row in load_corpus() {
        let actual = make_keywords(&row.parsed_description, &[], 15);
        if actual != row.keywords {
            mismatches.push(format!(
                "{:?}: expected {:?}, got {:?}",
                row.parsed_description, row.keywords, actual
            ));
        }
    }

    assert!(
        mismatches.is_empty(),
        "{} keyword mismatches:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}

#[test]
fn every_row_carries_the_parsed_description_the_reference_used() {
    let rows = load_corpus();

    let empty = rows
        .iter()
        .filter(|row| row.parsed_description.trim().is_empty())
        .count();
    let rewritten = rows
        .iter()
        .filter(|row| row.parsed_description != row.description)
        .count();

    assert_eq!(empty, 0, "a row has no parsed description");
    assert!(
        rewritten > 0,
        "no row differs from its input, so the corpus is not exercising the parser"
    );
}

#[test]
fn filename_matches_the_reference() {
    let mut mismatches = Vec::new();
    for row in load_corpus() {
        let actual = UcsFilename::new(row.cat_id.clone(), row.fx_name.clone())
            .with_creator_id("NONE")
            .with_source_id("NONE")
            .build()
            .expect("golden filename builds");
        if actual != row.filename {
            mismatches.push(format!(
                "{}: expected {:?}, got {:?}",
                row.cat_id, row.filename, actual
            ));
        }
    }

    assert!(
        mismatches.is_empty(),
        "{} filename mismatches:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}

#[test]
fn every_golden_cat_id_resolves_in_the_bundled_taxonomy() {
    let taxonomy = slate_ucs::Taxonomy::bundled().expect("bundled taxonomy");

    let unresolved: Vec<String> = load_corpus()
        .into_iter()
        .map(|row| row.cat_id)
        .filter(|cat_id| taxonomy.resolve(cat_id).is_none())
        .collect();

    assert!(unresolved.is_empty(), "unresolved CatIDs: {unresolved:?}");
}

#[test]
fn every_golden_filename_round_trips() {
    let mut failures = Vec::new();
    let mut hyphenated = 0usize;
    for row in load_corpus() {
        // The reference parser reads a hyphen in the FX block as a vendor category
        // prefix, so a name whose FXName contains a hyphen cannot round-trip. That is
        // reference behaviour, not a port difference; `parse_keeps_the_vendor_split`
        // pins it.
        if row.fx_name.contains('-') {
            hyphenated += 1;
            continue;
        }
        match slate_ucs::parse_ucs_filename(&row.filename, None) {
            Ok(parsed) if parsed.cat_id == row.cat_id && parsed.fx_name == row.fx_name => {}
            Ok(parsed) => failures.push(format!(
                "{}: parsed cat_id {:?} fx_name {:?}",
                row.filename, parsed.cat_id, parsed.fx_name
            )),
            Err(e) => failures.push(format!("{}: {e}", row.filename)),
        }
    }

    assert!(
        failures.is_empty(),
        "{} round-trip failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(
        hyphenated < 20,
        "{hyphenated} hyphenated FX names is more than the corpus should contain"
    );
}

#[test]
fn parse_keeps_the_vendor_split_for_a_hyphenated_fx_name() {
    let parsed = slate_ucs::parse_ucs_filename("CLOTHRip_Tearing Cotton T-shirt_NONE_NONE", None)
        .expect("parsed");

    assert_eq!(parsed.vendor_category.as_deref(), Some("Tearing Cotton T"));
    assert_eq!(parsed.fx_name, "shirt");
}
